// Masal önerisi: sunucu olmadığı için e-posta uygulamasını hazır mesajla açar ya da metni kopyalar
const EPOSTA = "lilithaley@gmail.com";   // önerilerin gideceği adres
$("#eposta").textContent = EPOSTA; $("#eposta").href = "mailto:" + EPOSTA;
$("#yil").textContent = new Date().getFullYear();   // altlıktaki yıl her yıl kendiliğinden güncellenir
function oneriMetni(){
  const v = (id) => $(id).value.trim();
  return ["Masalın adı: " + v("#oAd"), "Yöresi: " + (v("#oYore") || "-"),
    "Nereden duydum ya da okudum: " + (v("#oKaynak") || "-"), "Not: " + (v("#oNot") || "-"),
    v("#oKisi") ? "Gönderen: " + v("#oKisi") : ""].join("\n").trim();
}
function mailtoAdresi(){
  return "mailto:" + EPOSTA + "?subject=" + encodeURIComponent("Masal önerisi: " + $("#oAd").value.trim()) +
    "&body=" + encodeURIComponent(oneriMetni());
}
function oneriHazirMi(){
  if ($("#oAd").value.trim()) return true;
  $("#oMesaj").textContent = "Lütfen önerdiğin masalın adını yaz.";
  $("#oAd").focus();
  return false;
}
$("#oneri").addEventListener("submit", e => e.preventDefault());
$("#oMail").onclick = () => {
  if (!oneriHazirMi()) return;
  $("#oMesaj").textContent = "E-posta uygulaman açılıyor. Mesajı oradan gönderebilirsin.";
  window.location.href = mailtoAdresi();
};
$("#oKopya").onclick = async () => {
  if (!oneriHazirMi()) return;
  try { await navigator.clipboard.writeText(oneriMetni()); $("#oMesaj").textContent = "Öneri kopyalandı. İstediğin yere yapıştırıp gönderebilirsin."; }
  catch(e) { $("#oMesaj").textContent = "Kopyalanamadı. Metni elle seçip kopyalayabilirsin."; }
};

// Klavye gezinmesi (okuma ekranında): sağ ok sonraki, sol ok önceki masal, Esc listeye döner
document.addEventListener("keydown", e => {
  if (!acikId || e.ctrlKey || e.metaKey || e.altKey) return;
  if (/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) || e.target.isContentEditable) return;
  const i = MASALLAR.findIndex(m => m.id === acikId);
  if (e.key === "ArrowRight") git(MASALLAR[(i + 1) % MASALLAR.length].id);
  else if (e.key === "ArrowLeft") git(MASALLAR[(i + MASALLAR.length - 1) % MASALLAR.length].id);
  else if (e.key === "Escape") { if (!$("#ayarlar").hidden) $("#ayarAc").click(); else git(""); }
});
